/**
 * Explicit durable activity boundaries for WorkIt tasks.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Activity boundaries persist idempotency and terminal evidence for named task
 * segments. They do not persist arbitrary JavaScript stacks, scheduler state,
 * closures, or external side effects.
 */
import { type CancelReason, type TaskFn } from "../types/index.js";
type MaybePromise<T> = T | Promise<T>;
/** Schema version emitted by the activity boundary subpath. */
export type WorkItActivityVersion = "workit.activity.v1";
/** Terminal and non-terminal activity states. */
export type ActivityStatus = "started" | "completed" | "failed" | "cancelled";
/** Safe error evidence persisted for failed activity boundaries. */
export interface ActivityErrorEvidence {
    readonly name: string;
    readonly message: string;
}
/** Base activity record shared by all statuses. */
export interface ActivityRecordBase {
    readonly version: WorkItActivityVersion;
    readonly activityId: string;
    readonly inputHash: string;
    readonly status: ActivityStatus;
    readonly startedAt: number;
    readonly updatedAt: number;
    readonly name?: string;
    readonly activityVersion?: string;
}
/** Non-terminal activity record created when a boundary is claimed. */
export interface ActivityStartedRecord extends ActivityRecordBase {
    readonly status: "started";
}
/** Completed activity record with a cached, caller-owned result payload. */
export interface ActivityCompletedRecord<T = unknown> extends ActivityRecordBase {
    readonly status: "completed";
    readonly completedAt: number;
    readonly result: T;
}
/** Failed activity record with safe error evidence. */
export interface ActivityFailedRecord extends ActivityRecordBase {
    readonly status: "failed";
    readonly failedAt: number;
    readonly error: ActivityErrorEvidence;
}
/** Cancelled activity record with WorkIt's typed cancellation reason. */
export interface ActivityCancelledRecord extends ActivityRecordBase {
    readonly status: "cancelled";
    readonly cancelledAt: number;
    readonly cancelReason: CancelReason;
}
/** Persisted activity boundary record. */
export type ActivityRecord<T = unknown> = ActivityStartedRecord | ActivityCompletedRecord<T> | ActivityFailedRecord | ActivityCancelledRecord;
/** Result returned when a store attempts to claim an activity id. */
export interface ActivityStartResult {
    readonly status: "started" | "existing";
    readonly record: ActivityRecord;
}
/** Caller-owned activity store contract. */
export interface ActivityStore {
    start(record: ActivityStartedRecord): MaybePromise<ActivityStartResult>;
    finish(record: ActivityRecord): MaybePromise<ActivityRecord>;
    get(activityId: string): MaybePromise<ActivityRecord | undefined>;
}
/** Options for the in-memory activity store. */
export interface MemoryActivityStoreOptions {
    readonly maxRecords?: number;
}
/** Options for file-backed activity stores. */
export interface FileActivityStoreOptions {
    /** Directory that stores one JSON activity record per activity id. */
    readonly dir: string;
}
/** Explicit activity boundary contract. */
export interface ActivitySpec<TInput = unknown> {
    readonly activityId: string;
    readonly input: TInput;
    readonly name?: string;
    readonly version?: string;
}
/** Options for activity execution. */
export interface ActivityRunOptions {
    readonly clock?: () => number;
}
/** Error thrown when an activity id is reused with different input. */
export declare class ActivityConflictError extends Error {
    readonly activityId: string;
    constructor(activityId: string);
}
/** Error thrown when a stored non-completed activity cannot be executed again. */
export declare class ActivityNotRunnableError extends Error {
    readonly activityId: string;
    readonly status: ActivityStatus;
    constructor(activityId: string, status: ActivityStatus);
}
/** Error thrown when an activity payload cannot be converted to stable JSON. */
export declare class ActivitySerializationError extends Error {
    readonly activityId: string;
    constructor(activityId: string, message: string);
}
/** Creates a bounded in-memory activity store for tests and short-lived processes. */
export declare function createMemoryActivityStore(opts?: MemoryActivityStoreOptions): ActivityStore;
/** Creates a file-backed activity store for explicit restart/replay boundaries. */
export declare function createFileActivityStore(opts: FileActivityStoreOptions): ActivityStore;
/** Wraps a task body in an explicit persisted activity boundary. */
export declare function runActivity<TInput, TOutput>(store: ActivityStore, spec: ActivitySpec<TInput>, task: TaskFn<TOutput>, opts?: ActivityRunOptions): TaskFn<TOutput>;
export {};

/**
 * AI adapter utilities for WorkIt.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * This module is provider-neutral: callers bring provider functions, and WorkIt
 * supplies structured ownership, cancellation, token budgeting, and batch
 * failure policy. No network client is imported or initialized here.
 */
import type { CancelReason, Duration, RetryOpts, TaskContext, TaskFn, WorkOutput } from "../types/index.js";
/** Built-in token budget key for AI companion helpers. */
export declare const OpenAITokens: import("../index.js").ContextKey<import("../index.js").BudgetState>;
/** Built-in tool-call budget key for agent tool execution. */
export declare const AgentToolCalls: import("../index.js").ContextKey<import("../index.js").BudgetState>;
/** Provider contract for embedding one input inside a WorkIt task context. */
export interface EmbeddingProvider<I> {
    embed(input: I, ctx: TaskContext): Promise<readonly number[]>;
    countTokens?: (input: I) => number;
}
/** Provider contract for embedding a batch of inputs inside one task context. */
export interface BatchEmbeddingProvider<I> {
    embedBatch(inputs: readonly I[], ctx: TaskContext): Promise<readonly (readonly number[])[]>;
    countTokens?: (input: I) => number;
}
/** Provider contract for transcribing one chunk inside a WorkIt task context. */
export interface TranscriptionProvider<I> {
    transcribe(input: I, ctx: TaskContext): Promise<string>;
}
/** Options for provider-neutral embedding batches. */
export interface EmbedAllOptions<I> {
    concurrency?: number;
    onError?: "fail" | "continue" | "collect";
    countTokens?: (input: I) => number;
    retry?: number;
    timeout?: Duration;
}
/** Options for bad-batch bisection embedding. */
export interface EmbedBisectionOptions<I> {
    batchSize?: number;
    concurrency?: number;
    onError?: "fail" | "continue";
    countTokens?: (input: I) => number;
    classifyError?: (err: unknown, batch: readonly I[]) => "split" | "fail";
    retry?: number;
    timeout?: Duration;
}
/** Options for signal-aware streaming transcription. */
export interface TranscribeStreamOptions {
    signal?: AbortSignal;
}
/** Options for generic backpressured AI or provider streams. */
export interface StreamWithBackpressureOptions {
    concurrency?: number;
    retry?: number;
    timeout?: Duration;
    signal?: AbortSignal;
}
/** Replayable agent event emitted by `runAgent()`. */
export type AgentEvent = {
    type: "agent:started";
    seq: number;
    agentId: string;
    at: number;
} | {
    type: "agent:tool_started";
    seq: number;
    agentId: string;
    tool: string;
    at: number;
} | {
    type: "agent:tool_denied";
    seq: number;
    agentId: string;
    tool: string;
    capability: string;
    reason: AgentCapabilityDenialReason;
    at: number;
} | {
    type: "agent:tool_succeeded";
    seq: number;
    agentId: string;
    tool: string;
    at: number;
} | {
    type: "agent:tool_failed";
    seq: number;
    agentId: string;
    tool: string;
    error: string;
    at: number;
} | {
    type: "agent:tool_cancelled";
    seq: number;
    agentId: string;
    tool: string;
    reason: CancelReason;
    at: number;
} | {
    type: "agent:completed";
    seq: number;
    agentId: string;
    at: number;
} | {
    type: "agent:failed";
    seq: number;
    agentId: string;
    error: string;
    at: number;
};
/** Typed reason for declared agent tool capability denial. */
export type AgentCapabilityDenialReason = "capability_denied" | "capability_not_allowed";
/** Declared tool capability policy for `runAgent()`. This is not an OS sandbox. */
export interface AgentAuthorityPolicy {
    readonly allowedCapabilities?: readonly string[];
    readonly deniedCapabilities?: readonly string[];
}
/** Options for an agent run. */
export interface RunAgentOptions {
    readonly authority?: AgentAuthorityPolicy;
}
/** Error thrown when an agent tool declares a capability denied by policy. */
export declare class AgentCapabilityError extends Error {
    readonly tool: string;
    readonly capability: string;
    readonly reason: AgentCapabilityDenialReason;
    constructor(tool: string, capability: string, reason: AgentCapabilityDenialReason);
}
/** Budget charges and policies for one agent tool call. */
export interface AgentToolOptions {
    tokens?: number;
    cost?: number;
    toolCalls?: number;
    retry?: number | RetryOpts;
    timeout?: Duration;
    capability?: string;
}
/** Agent-scoped execution contract passed to `runAgent()`. */
export interface AgentScope {
    readonly id: string;
    readonly events: readonly AgentEvent[];
    tool<I, O>(name: string, input: I, fn: (input: I, ctx: TaskContext) => O | Promise<O>, opts?: AgentToolOptions): Promise<O>;
}
/** Result returned by `runAgent()`. */
export interface AgentRunResult<R> {
    result: R;
    events: readonly AgentEvent[];
}
/** Provider contract for stream-first LLM helpers. */
export interface LLMStreamProvider<I, O> {
    stream(input: I, ctx: TaskContext): AsyncIterable<O>;
}
/** Options for `streamLLM()`. */
export interface StreamLLMOptions {
    signal?: AbortSignal;
    buffer?: number;
}
/** Error type applications can throw when a provider rejects a mixed-quality batch. */
export declare class BadBatchError extends Error {
    static [Symbol.hasInstance](value: unknown): boolean;
    constructor(message?: string);
}
/** Wraps one AI task with structured task log events. */
export declare function wrapAI<T>(provider: string, task: TaskFn<T>): TaskFn<T>;
/** Runs an agent body with replayable local events and explicit tool contracts. */
export declare function runAgent<R>(body: (agent: AgentScope, ctx: TaskContext) => R | Promise<R>, opts?: RunAgentOptions): Promise<AgentRunResult<R>>;
/** Embeds all inputs with bounded concurrency and optional token budgeting. */
export declare function embedAll<I>(inputs: Iterable<I> | AsyncIterable<I>, provider: EmbeddingProvider<I>, opts?: EmbedAllOptions<I>): Promise<WorkOutput<readonly number[]>>;
/** Embeds batches and bisects provider-rejected bad batches down to item errors. */
export declare function embedAllBisection<I>(inputs: Iterable<I> | AsyncIterable<I>, provider: BatchEmbeddingProvider<I>, opts?: EmbedBisectionOptions<I>): Promise<WorkOutput<readonly number[]>>;
/** Transcribes an async stream of chunks sequentially with one scope per chunk. */
export declare function transcribeStream<I>(chunks: AsyncIterable<I>, provider: TranscriptionProvider<I>, opts?: TranscribeStreamOptions): AsyncIterable<string>;
/** Streams provider work with bounded concurrency, retry, timeout, and cancellation. */
export declare function streamWithBackpressure<I, O>(inputs: Iterable<I> | AsyncIterable<I>, fn: (input: I, ctx: TaskContext) => O | Promise<O>, opts?: StreamWithBackpressureOptions): AsyncIterable<O>;
/** Streams one LLM provider response while keeping provider work inside WorkIt ownership. */
export declare function streamLLM<I, O>(input: I, provider: LLMStreamProvider<I, O>, opts?: StreamLLMOptions): AsyncIterable<O>;

/**
 * Analysis helpers for WorkIt receipts, time policies, and event protocols.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * This subpath verifies already-declared WorkIt evidence and caller-provided
 * source protocol specifications. It does not parse arbitrary JavaScript source
 * or claim whole-program proofs.
 */
import type { TaskEvent } from "../types/index.js";
import type { TimePlan, TimePolicy } from "../time-policy/index.js";
import type { WorkItReceipt, WorkItReceiptEvent } from "../replay/index.js";
/** Analysis result status. */
export type AnalysisStatus = "pass" | "warn" | "fail";
/** Stable finding codes emitted by the analysis subpath. */
export type AnalysisFindingCode = "cleanup_evidence_missing" | "cleanup_timeout" | "deadline_infeasible" | "leaked_tasks" | "receipt_not_terminal" | "receipt_truncated" | "source_agent_tool_without_authority" | "source_durable_side_effect_without_evidence" | "source_parallel_without_bound" | "source_protocol_limit_exceeded" | "source_resource_without_cleanup" | "source_time_policy_unplanned" | "task_event_after_terminal" | "terminal_cause_missing" | "terminal_event_missing" | "terminal_failed" | "time_budget_exceeded" | "time_policy_warning";
/** Severity assigned to one analysis finding. */
export type AnalysisSeverity = "info" | "warn" | "error";
/** One typed verifier finding. */
export interface AnalysisFinding {
    readonly code: AnalysisFindingCode;
    readonly severity: AnalysisSeverity;
    readonly message: string;
    readonly taskId?: string;
    readonly receiptId?: string;
    readonly moduleId?: string;
    readonly functionId?: string;
    readonly operation?: string;
    readonly count?: number;
    readonly limit?: number;
    readonly estimatedMs?: number;
    readonly limitMs?: number;
}
/** Analysis report returned by verifier helpers. */
export interface AnalysisReport {
    readonly status: AnalysisStatus;
    readonly findings: readonly AnalysisFinding[];
}
/** Time-policy analysis report with the underlying plan attached. */
export interface TimePolicyAnalysisReport extends AnalysisReport {
    readonly plan: TimePlan;
}
/** Stable receipt verification checks. */
export type ReceiptVerificationCheckCode = "cleanup_evidence_recorded" | "no_orphaned_owned_tasks" | "terminal_cause_recorded" | "terminal_event_recorded" | "terminal_outcome_recorded";
/** One receipt verification check and its local status. */
export interface ReceiptVerificationCheck {
    readonly code: ReceiptVerificationCheckCode;
    readonly status: AnalysisStatus;
    readonly message: string;
    readonly count?: number;
}
/** Options for receipt verification. */
export interface ReceiptVerificationOptions {
    /** Require an observed root scope closing/closed timestamp, not only a closed snapshot. */
    readonly requireTerminalEvent?: boolean;
    /** Require observable cleanup failure/timeout evidence in the receipt. */
    readonly requireCleanupEvidence?: boolean;
}
/** Receipt verification report with explicit checks. */
export interface ReceiptVerificationReport extends AnalysisReport {
    readonly receiptId: string;
    readonly checks: readonly ReceiptVerificationCheck[];
}
/** Options for time-policy verification. */
export interface TimePolicyAnalysisOptions {
    readonly maxUpperBoundMs?: number;
}
/** Bounded source protocol operation understood by `verifySourceProtocol`. */
export type SourceProtocolOperation = "activity.run" | "agent.tool" | "authority.check" | "channel.backpressure" | "ctx.defer" | "durable.side_effect" | "promise.all" | "receipt.append" | "resource.acquire" | "resource.bracketLazy" | "resource.bracketShared" | "run.bracket" | "run.hedge" | "run.pool" | "run.retry" | "run.timeout" | "scope.acquire" | "scope.spawn" | "time_policy.plan" | "work.parallel";
/** Function class used by source protocol analysis. */
export type SourceProtocolFunctionKind = "activity" | "agent_tool" | "handler" | "resource" | "task";
/** One operation observed or declared inside a function body. */
export interface SourceProtocolUse {
    readonly operation: SourceProtocolOperation;
    readonly target?: string;
    readonly capability?: string;
    readonly line?: number;
}
/** One function-level source protocol contract. */
export interface SourceProtocolFunction {
    readonly functionId: string;
    readonly kind?: SourceProtocolFunctionKind;
    readonly uses: readonly SourceProtocolUse[];
}
/** One module-level source protocol contract. */
export interface SourceProtocolModule {
    readonly moduleId: string;
    readonly functions: readonly SourceProtocolFunction[];
}
/** Bounded source protocol specification supplied by the caller. */
export interface SourceProtocolSpec {
    readonly version?: "workit.source-protocol.v1";
    readonly modules: readonly SourceProtocolModule[];
}
/** Options that keep source protocol analysis bounded. */
export interface SourceProtocolAnalysisOptions {
    readonly maxModules?: number;
    readonly maxFunctions?: number;
    readonly maxUsesPerFunction?: number;
}
/** Source protocol report with checked-count evidence. */
export interface SourceProtocolAnalysisReport extends AnalysisReport {
    readonly checkedModules: number;
    readonly checkedFunctions: number;
    readonly checkedUses: number;
}
/** Verifies lifecycle invariants visible in one replay receipt. */
export declare function analyzeReceipt(receipt: WorkItReceipt): AnalysisReport;
/** Verifies explicit lifecycle evidence already present in a WorkIt receipt. */
export declare function verifyReceipt(receipt: WorkItReceipt, opts?: ReceiptVerificationOptions): ReceiptVerificationReport;
/** Verifies a declared time policy against planner warnings and optional SLA. */
export declare function verifyTimePolicy(policy: TimePolicy, opts?: TimePolicyAnalysisOptions): TimePolicyAnalysisReport;
/** Verifies a caller-provided source protocol contract for ownership gaps. */
export declare function verifySourceProtocol(spec: SourceProtocolSpec, opts?: SourceProtocolAnalysisOptions): SourceProtocolAnalysisReport;
/** Verifies basic lifecycle ordering over WorkIt task events. */
export declare function verifyScopeProtocol(events: readonly (TaskEvent | WorkItReceiptEvent)[]): AnalysisReport;

/**
 * Candidate failure and quality decision validation.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 */
import { type TaskContext } from "../types/index.js";
import type { AcceptanceDecision, CandidateActionDecision, CandidateFailureDecision, FirstAcceptableOptions } from "./types.js";
/** Returns the safe built-in classification for a known WorkIt runtime error. */
export declare function classifyWorkItFailure(error: unknown): CandidateFailureDecision | undefined;
export declare class ClassifiedCandidateError extends Error {
    readonly decision: CandidateActionDecision;
    readonly original: unknown;
    constructor(original: unknown, decision: CandidateActionDecision);
}
export declare class CandidateCallbackError extends Error {
    readonly original: unknown;
    constructor(original: unknown);
}
export declare function classifyCandidateError<C, T>(error: unknown, candidate: C, ctx: TaskContext, classify: FirstAcceptableOptions<C, T>["classifyFailure"]): Promise<ClassifiedCandidateError>;
export declare function normalizeAcceptanceDecision(value: unknown): AcceptanceDecision;

/**
 * Bounded candidate evidence mapping over the shared attempt recorder.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 */
import type { WorkItAttemptEvidence } from "../replay/index.js";
import type { CandidateAttemptDecision, CandidateAttemptEvidence } from "./types.js";
export interface CandidateDecisionRecord {
    readonly candidateIndex: number;
    readonly decision: CandidateAttemptDecision;
    readonly reasonCode?: string;
}
export declare function mapCandidateEvidence(attempts: readonly WorkItAttemptEvidence[], decisions: readonly CandidateDecisionRecord[]): readonly CandidateAttemptEvidence[];

/**
 * Deterministic candidate selection with typed failure and quality policy.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Candidate execution is sequential and may repeat side effects. Callers own
 * idempotency for side-effecting operations.
 */
import type { CandidateFailureDecision, CandidateRunResult, FirstAcceptableOptions } from "./types.js";
export type { AcceptanceDecision, CandidateActionDecision, CandidateAttemptDecision, CandidateAttemptEvidence, CandidateFailureDecision, CandidateRetryPolicy, CandidateRunResult, FailureDisposition, FirstAcceptableOptions, } from "./types.js";
/** Returns the safe built-in classification for a known WorkIt runtime error. */
export declare function classifyWorkItFailure(error: unknown): CandidateFailureDecision | undefined;
/** Selects the first semantically acceptable result in deterministic candidate order. */
export declare function firstAcceptable<C, T>(candidates: readonly C[], opts: FirstAcceptableOptions<C, T>): Promise<CandidateRunResult<C, T>>;

/**
 * Public contracts for deterministic candidate selection.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 */
import type { AttemptRecorderOptions, WorkItAttemptEvidence } from "../replay/index.js";
import type { RetryOpts, TaskContext } from "../types/index.js";
/** Policy outcome assigned to a failed candidate attempt. */
export type FailureDisposition = "retry_same_candidate" | "try_next_candidate" | "terminal" | "cancelled" | "requires_user_input";
/** Bounded, machine-readable classification of a candidate failure. */
export interface CandidateFailureDecision {
    readonly disposition: FailureDisposition;
    readonly reasonCode: string;
}
/** Failure decisions a provider classifier may return. Real cancellation is detected by WorkIt. */
export interface CandidateActionDecision extends CandidateFailureDecision {
    readonly disposition: Exclude<FailureDisposition, "cancelled">;
}
/** Semantic quality decision kept separate from transport success. */
export type AcceptanceDecision = {
    readonly accepted: true;
} | {
    readonly accepted: false;
    readonly reasonCode: string;
};
/** Candidate-level interpretation of one recorded task-body invocation. */
export type CandidateAttemptDecision = CandidateActionDecision["disposition"] | "quality_rejected" | "accepted";
/** Bounded attempt evidence enriched with candidate and quality policy facts. */
export interface CandidateAttemptEvidence extends WorkItAttemptEvidence {
    readonly candidateIndex: number;
    readonly decision: CandidateAttemptDecision;
}
interface CandidateResultEvidence {
    readonly evidence: readonly CandidateAttemptEvidence[];
    readonly droppedEvidence: number;
}
/** Exhaustive expected outcome of a candidate selection run. */
export type CandidateRunResult<C, T> = (CandidateResultEvidence & {
    readonly status: "accepted";
    readonly candidate: C;
    readonly candidateIndex: number;
    readonly value: T;
}) | (CandidateResultEvidence & {
    readonly status: "exhausted";
}) | (CandidateResultEvidence & {
    readonly status: "terminal";
    readonly reasonCode: string;
    readonly error: unknown;
}) | (CandidateResultEvidence & {
    readonly status: "requires_user_input";
    readonly reasonCode: string;
});
/** Retry policy whose admission predicate is owned by the failure classifier. */
export type CandidateRetryPolicy = number | Omit<RetryOpts, "retryIf">;
/** Candidate selection policy and bounded evidence controls. */
export interface FirstAcceptableOptions<C, T> {
    readonly execute: (candidate: C, ctx: TaskContext) => T | Promise<T>;
    readonly accept: (value: T, candidate: C, ctx: TaskContext) => AcceptanceDecision | Promise<AcceptanceDecision>;
    readonly classifyFailure: (error: unknown, candidate: C, ctx: TaskContext) => CandidateActionDecision | Promise<CandidateActionDecision>;
    readonly retry?: CandidateRetryPolicy;
    readonly maxCandidates?: number;
    readonly deadlineAt?: number | Date;
    readonly evidence?: AttemptRecorderOptions;
    readonly candidateMetadata?: (candidate: C, candidateIndex: number) => Readonly<Record<string, unknown>> | undefined;
}
export {};

/**
 * Bounded async channel primitive.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Channels provide explicit backpressure for producer/consumer pipelines. They
 * are intentionally local in-memory coordination primitives; durable queues,
 * cross-process delivery, and replay belong in application infrastructure.
 */
export interface ChannelOpOptions {
    signal?: AbortSignal;
}
export type ChannelReceive<T> = {
    done: false;
    value: T;
} | {
    done: true;
    reason?: unknown;
};
export interface Channel<T> extends AsyncIterable<T> {
    readonly capacity: number;
    readonly size: number;
    readonly closed: boolean;
    send(value: T, opts?: ChannelOpOptions): Promise<void>;
    receive(opts?: ChannelOpOptions): Promise<ChannelReceive<T>>;
    close(reason?: unknown): void;
}
export declare class ChannelClosedError extends Error {
    readonly reason?: unknown;
    constructor(reason?: unknown);
}
/** Creates a bounded FIFO channel with explicit producer backpressure. */
export declare function createChannel<T>(opts?: {
    capacity?: number;
}): Channel<T>;

/**
 * Typed cancellation contract helpers for WorkIt tasks.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * This subpath adds compile-time composition contracts around existing WorkIt
 * task functions. It records declared intent at API boundaries; it does not
 * prove that a task body observes `ctx.signal` at every await point.
 */
import type { Duration, ScopeOpts, TaskFn, TaskHandle, TaskOpts } from "../types/index.js";
declare const contractBrand: unique symbol;
/** Declared cancellation contract visible at typed composition boundaries. */
export type TaskCancellationContract = {
    readonly kind: "cancellable";
} | {
    readonly kind: "shielded";
    readonly timeout: Duration;
    readonly discardReason?: string;
};
/** Task declared as normal cancellable WorkIt child work. */
export type CancellableTask<T> = TaskFn<T> & {
    readonly [contractBrand]: "cancellable";
};
/** Task declared as timeout-bounded shielded work. */
export type ShieldedTask<T> = TaskFn<T> & {
    readonly [contractBrand]: "shielded";
};
/** Spawner used by `typedGroup` to enforce task cancellation contracts. */
export interface TypedTaskSpawner {
    <T>(task: CancellableTask<T>, opts?: TaskOpts): TaskHandle<T>;
    /** Spawns cancellable background work that remains owned by the scope. */
    background<T>(task: CancellableTask<T>): TaskHandle<T>;
    /** Spawns explicit timeout-bounded shielded work. */
    shielded<T>(task: ShieldedTask<T>, opts?: TaskOpts): TaskHandle<T>;
}
/** Declares a WorkIt task as ordinary cancellable child work. */
export declare function cancellable<T>(task: TaskFn<T>): CancellableTask<T>;
/** Declares a task as shielded by WorkIt's timeout-bounded uncancellable wrapper. */
export declare function shielded<T>(task: TaskFn<T>, opts: {
    timeout: Duration;
}): ShieldedTask<T>;
/** Converts cancellable work into explicit shielded work with a named discard reason. */
export declare function discardCancellation<T>(task: CancellableTask<T>, discardReason: string, opts: {
    timeout: Duration;
}): ShieldedTask<T>;
/** Opens a WorkIt group whose normal spawner accepts only declared cancellable tasks. */
export declare function typedGroup<R>(body: (task: TypedTaskSpawner) => Promise<R>, opts?: ScopeOpts): Promise<R>;
/** Returns the declared task cancellation contract, when one was declared. */
export declare function getTaskContract(task: TaskFn<unknown>): TaskCancellationContract | undefined;
/** Reports whether a task was declared through `cancellable(...)`. */
export declare function isCancellableTask<T>(task: TaskFn<T>): task is CancellableTask<T>;
/** Reports whether a task was declared through `shielded(...)` or `discardCancellation(...)`. */
export declare function isShieldedTask<T>(task: TaskFn<T>): task is ShieldedTask<T>;
export {};

/**
 * Snapshot diagnostics for WorkIt scopes.
 *
 * @author Admilson B. F. Cossa
 * SPDX-License-Identifier: Apache-2.0
 *
 * Diagnostics are pure over existing scope snapshots and typed engine events.
 * They do not subscribe to runtime state or pull in the core runtime, keeping
 * the SRE inspection surface available as an opt-in package subpath.
 */
import type { ScopeId, ScopeSnapshot, TaskEvent, TaskId } from "../types/index.js";
/** Overall health result for a diagnostics report. */
export type DiagnosticsStatus = "ok" | "needs_attention";
/** Severity assigned to an SRE diagnostics finding. */
export type DiagnosticsSeverity = "info" | "warn" | "error";
/** Stable finding code emitted by the diagnostics subpath. */
export type DiagnosticsFindingCode = "old_pending_task" | "pending_child_scope" | "scope_cancelling" | "cleanup_timeout";
/** Options for diagnosing an existing scope snapshot. */
export interface DiagnosticsOptions {
    /** Wall-clock timestamp used for age calculations. Defaults to `Date.now()`. */
    now?: number;
    /** Age threshold for pending or running tasks. Defaults to 30 seconds. */
    staleTaskMs?: number;
    /** Optional bounded event window to correlate cleanup timeout events. */
